<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, itemsOf } from '../api.js'
import { asLines, asText, formatTime, limitationText } from '../labels.js'
import StatePanel from '../components/StatePanel.vue'

const props = defineProps({ user: Object })
const items = ref([]), loading = ref(false), error = ref(null), editor = ref(false), saving = ref(false), saveError = ref(null), checking = ref(''), checks = reactive({}), checkErrors = reactive({}), query = ref('')
const admin = computed(() => props.user?.role === 'admin')
const blank = () => ({ id: '', name: '', base_url: '', credential_ref: '', collector_ref: '', erpnext_version: '', frappe_version: '', installed_apps: '', log_source: 'none', allowed_services: [], model_consent: false })
const form = reactive(blank())
const filtered = computed(() => items.value.filter(item => !query.value.trim() || [item.name, item.base_url, item.erpnext_version, item.frappe_version].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())))
async function load() { loading.value = true; error.value = null; try { items.value = itemsOf(await api.environments()) } catch (failure) { error.value = failure } finally { loading.value = false } }
function edit(item) { const empty = blank(); for (const key of Object.keys(empty)) form[key] = item?.[key] ?? empty[key]; form.installed_apps = Array.isArray(item?.installed_apps) ? item.installed_apps.join('\n') : ''; form.allowed_services = Array.isArray(item?.allowed_services) ? [...item.allowed_services] : []; saveError.value = null; editor.value = true }
async function save() {
  if (!form.name.trim() || !form.base_url.trim() || !form.credential_ref.trim()) { saveError.value = { message: '请填写环境名称、ERP 地址和已在服务端配置的凭据别名。' }; return }
  if (!/^15\.\d+\.\d+$/.test(form.erpnext_version.trim()) || !/^15\.\d+\.\d+$/.test(form.frappe_version.trim())) { saveError.value = { message: '请填写实际完整版本号；首版已审查 ERPNext 15.85.1 与 Frappe 15.87.0。' }; return }
  if (!/^[a-zA-Z0-9_-]{1,64}$/.test(form.credential_ref.trim())) { saveError.value = { message: '凭据别名仅允许字母、数字、下划线和连字符，最长 64 字。' }; return }
  if (form.collector_ref.trim() && !/^[a-zA-Z0-9_-]{1,64}$/.test(form.collector_ref.trim())) { saveError.value = { message: '只读采集器别名仅允许字母、数字、下划线和连字符，最长 64 字。' }; return }
  try { const url = new URL(form.base_url); if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.pathname !== '/' || url.search || url.hash) throw new Error() } catch { saveError.value = { message: 'ERP 地址必须是无账号密码、无路径或查询参数的完整 HTTP 或 HTTPS 站点地址。' }; return }
  const data = { ...form, name: form.name.trim(), base_url: form.base_url.trim(), credential_ref: form.credential_ref.trim(), collector_ref: form.collector_ref.trim() || null, installed_apps: asLines(form.installed_apps), allowed_services: [...form.allowed_services] }; delete data.id
  saving.value = true; saveError.value = null
  try { if (form.id) await api.update('environments', form.id, data); else await api.create('environments', data); editor.value = false; await load(); ElMessage.success('环境配置已保存；请再运行能力检查。') } catch (failure) { saveError.value = failure } finally { saving.value = false }
}
async function check(item) { checking.value = item.id; delete checkErrors[item.id]; try { checks[item.id] = { data: await api.action('environments', item.id, 'check'), at: new Date().toISOString() } } catch (failure) { delete checks[item.id]; checkErrors[item.id] = failure } finally { checking.value = '' } }
async function remove(item) { try { await ElMessageBox.confirm(`删除环境“${item.name}”的工作台配置？此操作不修改 ERP 系统。`, '确认删除环境', { type: 'warning', confirmButtonText: '删除配置', cancelButtonText: '取消' }); await api.remove('environments', item.id); delete checks[item.id]; await load(); ElMessage.success('环境配置已删除。') } catch (failure) { if (failure !== 'cancel' && failure !== 'close') error.value = failure } }
function checkMessages(data) { return [...(data?.missing_information || data?.missing || []), ...(data?.limitations || data?.capabilities?.limitations || [])] }
function checkPayload(data) { return data?.capabilities?.payload || data?.capabilities || data || {} }
function readPermissions(data) { return Object.entries(checkPayload(data).read_permissions || {}).map(([name, granted]) => ({ name, granted })) }
function runtimeSnapshot(data) { const value = data?.runtime_collector?.snapshot; if (typeof value === 'string') { try { return JSON.parse(value) } catch { return {} } } return value && typeof value === 'object' ? value : {} }
function runtimeServices(data) { return Object.entries(runtimeSnapshot(data).payload?.services || {}).map(([name, value]) => ({ name, ...value })) }
onMounted(load)
</script>

<template>
  <section>
    <div class="page-heading"><div><h1>环境与只读能力</h1><p>检查当前版本、对象权限与可用数据源。凭据只通过服务端别名引用。</p></div><el-button type="primary" :disabled="!admin" @click="edit()">新增环境</el-button></div>
    <el-alert v-if="!admin" title="当前账号可查看已授权环境和运行能力检查；配置变更需要管理员。" type="info" :closable="false" class="space-bottom" />
    <div class="panel filter-bar"><el-input v-model="query" clearable placeholder="检索环境名称、地址或版本" class="search-input" /><el-button :loading="loading" @click="load">刷新</el-button></div>
    <StatePanel :loading="loading" :error="error" :empty="!filtered.length" empty-text="没有可访问的环境，请由管理员添加配置并分配访问权限" @retry="load">
      <article v-for="item in filtered" :key="item.id" class="panel environment-card"><div class="case-heading"><div><span class="eyebrow">授权环境 · {{ item.id }}</span><h2>{{ item.name }}</h2></div><div class="action-row"><el-button type="primary" plain :loading="checking === item.id" :disabled="!!checking && checking !== item.id" @click="check(item)">连接与能力检查</el-button><el-button :disabled="!admin" @click="edit(item)">编辑</el-button><el-button type="danger" plain :disabled="!admin" @click="remove(item)">删除配置</el-button></div></div><el-descriptions :column="2" border><el-descriptions-item label="ERP 地址">{{ item.base_url }}</el-descriptions-item><el-descriptions-item label="凭据别名">{{ item.credential_ref }}</el-descriptions-item><el-descriptions-item label="ERPNext 版本">{{ item.erpnext_version || '未配置；以探测结果为准' }}</el-descriptions-item><el-descriptions-item label="Frappe 版本">{{ item.frappe_version || '未配置；以探测结果为准' }}</el-descriptions-item><el-descriptions-item label="已配置应用">{{ item.installed_apps?.join('、') || '未配置' }}</el-descriptions-item><el-descriptions-item label="日志来源">{{ item.log_source === 'erp-api' ? '已授权 ERP 日志 API' : '无日志数据源' }}</el-descriptions-item><el-descriptions-item label="只读运行采集器">{{ item.collector_ref || '未配置' }}</el-descriptions-item><el-descriptions-item label="允许读取的服务">{{ item.allowed_services?.join('、') || '未授权运行环境服务' }}</el-descriptions-item><el-descriptions-item label="模型数据授权">{{ item.model_consent ? '允许发送已脱敏诊断上下文' : '未授权模型；仅使用确定性规则' }}</el-descriptions-item></el-descriptions>
        <el-alert v-if="checkErrors[item.id]" :title="checkErrors[item.id].status === 403 ? '权限不足：' + checkErrors[item.id].message : checkErrors[item.id].message" type="error" :closable="false" class="space-top" />
        <div v-if="checks[item.id]" class="capability-result space-top"><h3>实际检查结果</h3><p class="muted">本次采集时间：{{ formatTime(checks[item.id].at) }}。接口可用只说明本次读取成功，不代表业务故障已消除。</p><el-alert v-if="checkMessages(checks[item.id].data).length" title="部分能力或信息缺失" type="warning" :closable="false"><ul><li v-for="(line, index) in checkMessages(checks[item.id].data)" :key="index">{{ limitationText(asText(line)) }}</li></ul></el-alert><el-descriptions :column="3" border class="space-top"><el-descriptions-item label="实际 ERPNext 版本">{{ checkPayload(checks[item.id].data).erpnext_version || '未取得' }}</el-descriptions-item><el-descriptions-item label="实际 Frappe 版本">{{ checkPayload(checks[item.id].data).frappe_version || '未取得' }}</el-descriptions-item><el-descriptions-item label="版本适配"><el-tag :type="checkPayload(checks[item.id].data).version_supported === true ? 'success' : 'warning'">{{ checkPayload(checks[item.id].data).version_supported === true ? '已匹配已审查版本' : '未匹配或无法确认' }}</el-tag></el-descriptions-item><el-descriptions-item label="站点时区">{{ checkPayload(checks[item.id].data).site_timezone || '未取得' }}</el-descriptions-item><el-descriptions-item label="操作用户提交权限">{{ checkPayload(checks[item.id].data).operator_submit_permission === 'unknown' ? '未核验' : checkPayload(checks[item.id].data).operator_submit_permission || '未取得' }}</el-descriptions-item><el-descriptions-item label="运行环境健康">{{ checks[item.id].data.runtime_collector ? (checks[item.id].data.runtime_collector.status === 'success' ? '独立采集已完成；见服务结果' : '独立采集未完成') : checkPayload(checks[item.id].data).runtime_health === 'not_configured' ? '未配置数据源' : checkPayload(checks[item.id].data).runtime_health || '未取得' }}</el-descriptions-item></el-descriptions><h3 v-if="readPermissions(checks[item.id].data).length">对象级读取权限</h3><p v-if="readPermissions(checks[item.id].data).length" class="muted">对象权限不代表该类型的全部单据可见；具体读取仍受环境及单据权限限制。</p><el-table v-if="readPermissions(checks[item.id].data).length" :data="readPermissions(checks[item.id].data)" size="small"><el-table-column prop="name" label="业务对象" min-width="220" /><el-table-column label="当前账号读取权限" min-width="180"><template #default="{row}"><el-tag :type="row.granted === true ? 'success' : 'danger'">{{ row.granted === true ? '具备读取权限' : row.granted === false ? '无读取权限' : '尚未确认' }}</el-tag></template></el-table-column></el-table><div v-if="checks[item.id].data.runtime_collector" class="space-top"><h3>独立运行采集来源</h3><el-alert v-if="checks[item.id].data.runtime_collector.status !== 'success'" :title="'采集未完成：' + (checks[item.id].data.runtime_collector.error || '未提供错误说明')" type="warning" :closable="false" /><template v-else><p class="muted">来源 {{ runtimeSnapshot(checks[item.id].data).source || '服务端绑定的只读采集器' }} · {{ formatTime(runtimeSnapshot(checks[item.id].data).collected_at) }}。运行健康不等于库存或发货业务完成。</p><el-table :data="runtimeServices(checks[item.id].data)" size="small"><el-table-column prop="name" label="限定服务" min-width="160" /><el-table-column prop="category" label="类别" width="140" /><el-table-column prop="state" label="容器状态" width="140" /><el-table-column prop="health" label="健康检查" width="140" /><el-table-column prop="ping" label="Redis PING" width="140" /></el-table></template></div><el-collapse class="space-top"><el-collapse-item title="展开完整版本、权限与数据源结果" :name="item.id"><pre class="evidence-content">{{ asText(checks[item.id].data) }}</pre></el-collapse-item></el-collapse></div><p v-else-if="!checkErrors[item.id]" class="muted">尚未运行本次连接检查，不能据此判断版本、权限或能力可用。</p>
      </article>
    </StatePanel>
    <el-dialog v-model="editor" :title="form.id ? '编辑环境配置' : '新增授权环境'" width="720px" :close-on-click-modal="false"><el-alert title="只填写服务端凭据别名，不输入 API Key、密码或 Token。环境必须在服务端授权范围内。" type="info" :closable="false" class="space-bottom" /><el-alert v-if="saveError" :title="saveError.message" type="error" :closable="false" class="space-bottom" /><el-form label-position="top"><el-form-item label="环境名称"><el-input v-model="form.name" maxlength="120" /></el-form-item><el-form-item label="ERPNext 地址"><el-input v-model="form.base_url" placeholder="https://授权站点" /></el-form-item><el-form-item label="服务端凭据别名"><el-input v-model="form.credential_ref" placeholder="部署管理员配置的别名" /></el-form-item><el-form-item label="服务端只读运行采集器别名 · 可选"><el-input v-model="form.collector_ref" placeholder="仅引用服务端已配置的只读采集器，例如 erp-lab；不填写密钥" /></el-form-item><p class="muted">未引用采集器时不会取得数据库、Redis 或容器健康证据。服务授权不会自动创建连接。</p><div class="form-columns"><el-form-item label="实际 ERPNext 完整版本 · 必填"><el-input v-model="form.erpnext_version" /></el-form-item><el-form-item label="实际 Frappe 完整版本 · 必填"><el-input v-model="form.frappe_version" /></el-form-item></div><div class="form-columns"><el-form-item label="已安装应用 · 每行一项"><el-input v-model="form.installed_apps" type="textarea" :rows="3" /></el-form-item><el-form-item label="允许运行采集器读取的服务"><el-checkbox-group v-model="form.allowed_services"><el-checkbox value="application" :disabled="!form.collector_ref.trim()">应用容器与限定日志</el-checkbox><el-checkbox value="database" :disabled="!form.collector_ref.trim()">数据库连通性</el-checkbox><el-checkbox value="redis" :disabled="!form.collector_ref.trim()">Redis 连通性</el-checkbox></el-checkbox-group></el-form-item></div><el-form-item label="日志来源"><el-select v-model="form.log_source"><el-option label="无已授权日志数据源" value="none" /><el-option label="已授权 ERP 日志 API" value="erp-api" /></el-select></el-form-item><el-checkbox v-model="form.model_consent">允许配置的模型处理已脱敏诊断上下文（凭据不会发送）</el-checkbox></el-form><template #footer><el-button @click="editor = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存配置</el-button></template></el-dialog>
  </section>
</template>
